export function renderLesson(toolId, loadExample) {
  const lesson = lessons[toolId];
  const $ = (id) => document.getElementById(id);
  $("input-guide").textContent = lesson.input;
  $("lesson-title").textContent = lesson.title;
  $("lesson-meaning").textContent = lesson.meaning;
  $("lesson-steps").replaceChildren(
    ...lesson.steps.map((text) => {
      const item = document.createElement("li");
      item.textContent = text;
      return item;
    }),
  );
  $("lesson-tip").textContent = lesson.tip;
  $("lesson-examples").replaceChildren(
    ...lesson.examples.map((example) => {
      const button = document.createElement("button");
      button.type = "button";
      button.textContent = example.label + " ↗";
      button.onclick = () => loadExample(example.values);
      return button;
    }),
  );
}

